using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    const int total = n * m;
    const int INF = numeric_limits<int>::max();

    vector<int> match(total, -1);
    vector<int> dist(total, -1);
    vector<int> q(total);

    const int dx[8] = {1, 1, -1, -1, 2, 2, -2, -2};
    const int dy[8] = {2, -2, 2, -2, 1, -1, 1, -1};

    auto id = [m](int x, int y) {
        return x * m + y;
    };

    int augmentDistance = INF;

    auto bfs = [&]() {
        int front = 0, back = 0;
        augmentDistance = INF;
        fill(dist.begin(), dist.end(), -1);

        for (int x = 0; x < n; ++x) {
            for (int y = 0; y < m; ++y) {
                if (((x + y) & 1) == 0) continue;

                int u = id(x, y);
                if (match[u] == -1) {
                    dist[u] = 0;
                    q[back++] = u;
                }
            }
        }

        while (front < back) {
            int u = q[front++];
            if (dist[u] + 1 > augmentDistance) continue;

            int x = u / m;
            int y = u % m;

            for (int k = 0; k < 8; ++k) {
                int nx = x + dx[k];
                int ny = y + dy[k];

                if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;

                int v = id(nx, ny);
                int paired = match[v];

                if (paired == -1) {
                    augmentDistance = min(augmentDistance, dist[u] + 1);
                } else if (dist[paired] == -1 &&
                           dist[u] + 1 < augmentDistance) {
                    dist[paired] = dist[u] + 1;
                    q[back++] = paired;
                }
            }
        }

        return augmentDistance != INF;
    };

    function<bool(int)> dfs = [&](int u) {
        int x = u / m;
        int y = u % m;

        for (int k = 0; k < 8; ++k) {
            int nx = x + dx[k];
            int ny = y + dy[k];

            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;

            int v = id(nx, ny);
            int paired = match[v];

            if (paired == -1) {
                if (dist[u] + 1 != augmentDistance) continue;
            } else {
                if (dist[paired] != dist[u] + 1 || !dfs(paired)) continue;
            }

            match[u] = v;
            match[v] = u;
            return true;
        }

        dist[u] = -1;
        return false;
    };

    int maximumMatching = 0;

    while (bfs()) {
        for (int x = 0; x < n; ++x) {
            for (int y = 0; y < m; ++y) {
                if (((x + y) & 1) == 0) continue;

                int u = id(x, y);
                if (match[u] == -1 && dfs(u)) {
                    ++maximumMatching;
                }
            }
        }
    }

    cout << 1LL * n * m - maximumMatching << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, m;
vector<int> matchVertex, distLevel;
int shortestPath;

const int dx[8] = {-2, -2, -1, -1, 1, 1, 2, 2};
const int dy[8] = {-1, 1, -2, 2, -2, 2, -1, 1};

inline int id(int x, int y) {
    return x * m + y;
}

bool bfs() {
    queue<int> q;
    const int INF = numeric_limits<int>::max();

    fill(distLevel.begin(), distLevel.end(), INF);
    shortestPath = INF;

    for (int x = 0; x < n; ++x) {
        for (int y = (x + 1) & 1; y < m; y += 2) {
            int u = id(x, y);
            if (matchVertex[u] == -1) {
                distLevel[u] = 0;
                q.push(u);
            }
        }
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (distLevel[u] >= shortestPath) continue;

        int x = u / m;
        int y = u % m;

        for (int k = 0; k < 8; ++k) {
            int nx = x + dx[k];
            int ny = y + dy[k];

            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;

            int v = id(nx, ny);
            int nextLeft = matchVertex[v];

            if (nextLeft == -1) {
                shortestPath = distLevel[u] + 1;
            } else if (distLevel[nextLeft] == INF) {
                distLevel[nextLeft] = distLevel[u] + 1;
                q.push(nextLeft);
            }
        }
    }

    return shortestPath != INF;
}

bool dfs(int u) {
    int x = u / m;
    int y = u % m;

    for (int k = 0; k < 8; ++k) {
        int nx = x + dx[k];
        int ny = y + dy[k];

        if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;

        int v = id(nx, ny);
        int nextLeft = matchVertex[v];

        if (nextLeft == -1) {
            if (distLevel[u] + 1 != shortestPath) continue;
            matchVertex[u] = v;
            matchVertex[v] = u;
            return true;
        }

        if (distLevel[nextLeft] == distLevel[u] + 1 && dfs(nextLeft)) {
            matchVertex[u] = v;
            matchVertex[v] = u;
            return true;
        }
    }

    distLevel[u] = numeric_limits<int>::max();
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;

    int vertices = n * m;
    matchVertex.assign(vertices, -1);
    distLevel.resize(vertices);

    int maximumMatching = 0;

    while (bfs()) {
        for (int x = 0; x < n; ++x) {
            for (int y = (x + 1) & 1; y < m; y += 2) {
                int u = id(x, y);
                if (matchVertex[u] == -1 && dfs(u)) {
                    ++maximumMatching;
                }
            }
        }
    }

    cout << 1LL * n * m - maximumMatching << '\n';
    return 0;
}

