#include <bits/stdc++.h>
using namespace std;

class HopcroftKarp {
    int n, m, shortest;
    vector<int> match, dist, leftVertices;
    static constexpr int dx[8] = {1, 1, -1, -1, 2, 2, -2, -2};
    static constexpr int dy[8] = {2, -2, 2, -2, 1, -1, 1, -1};

    bool bfs() {
        fill(dist.begin(), dist.end(), -1);
        queue<int> q;
        shortest = INT_MAX;

        for (int u : leftVertices) {
            if (match[u] == -1) {
                dist[u] = 0;
                q.push(u);
            }
        }

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            if (dist[u] >= shortest) continue;

            int x = u / m;
            int y = u % m;

            for (int k = 0; k < 8; ++k) {
                int nx = x + dx[k];
                int ny = y + dy[k];
                if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;

                int v = nx * m + ny;
                int nextLeft = match[v];

                if (nextLeft == -1) {
                    shortest = dist[u] + 1;
                } else if (dist[nextLeft] == -1) {
                    dist[nextLeft] = dist[u] + 1;
                    q.push(nextLeft);
                }
            }
        }

        return shortest != INT_MAX;
    }

    bool dfs(int u) {
        int x = u / m;
        int y = u % m;

        for (int k = 0; k < 8; ++k) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (nx < 0 || nx >= n || ny < 0 || ny >= m) continue;

            int v = nx * m + ny;
            int nextLeft = match[v];

            if (nextLeft == -1) {
                if (dist[u] + 1 != shortest) continue;
            } else {
                if (dist[nextLeft] != dist[u] + 1 || !dfs(nextLeft))
                    continue;
            }

            match[u] = v;
            match[v] = u;
            return true;
        }

        dist[u] = -1;
        return false;
    }

public:
    HopcroftKarp(int rows, int columns)
        : n(rows), m(columns), match(rows * columns, -1),
          dist(rows * columns, -1) {
        leftVertices.reserve((rows * columns + 1) / 2);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < m; ++j)
                if ((i + j) & 1)
                    leftVertices.push_back(i * m + j);
    }

    int maximumMatching() {
        int result = 0;
        while (bfs()) {
            for (int u : leftVertices)
                if (match[u] == -1 && dfs(u))
                    ++result;
        }
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    HopcroftKarp solver(n, m);
    int maximumMatching = solver.maximumMatching();

    cout << 1LL * n * m - maximumMatching << '\n';
    return 0;
}

